/** Picklist intake and the multi-carton end-control. Products are never approved by OCR alone. */
public class PicklistActivity extends AppCompatActivity {
    private Context words;private String language="nl";private ThemeSkin skin;
    PicklistJob job;PicklistData data=new PicklistData();
    private final java.util.concurrent.ExecutorService worker=Executors.newSingleThreadExecutor();
    private ProcessCameraProvider provider;private Preview previewUseCase;private ImageCapture camera;private PreviewView preview;
    private LinearLayout root,body;private TextView message;private String screen="capture";private boolean busy,destroyed,reviewAcknowledged;
    private Toast currentToast;private File exportFile;private final ProductCatalog lotColours=new ProductCatalog();
    private final ActivityResultLauncher<String> permission=registerForActivityResult(new ActivityResultContracts.RequestPermission(),ok->{if(ok)capturePage();else toast(s("pl_camera_denied"));});
    private final ActivityResultLauncher<String[]> documents=registerForActivityResult(new ActivityResultContracts.OpenMultipleDocuments(),uris->{if(!uris.isEmpty())importDocuments(uris);});
    private final ActivityResultLauncher<Intent> scan=registerForActivityResult(new ActivityResultContracts.StartActivityForResult(),r->{try{job=PicklistJob.load(this,job.directory.getPath());dashboard();}catch(Exception e){fail(e);}});
    private final ActivityResultLauncher<String> save=registerForActivityResult(new ActivityResultContracts.CreateDocument("application/zip"),uri->{if(uri!=null&&exportFile!=null)worker.execute(()->{try(InputStream in=new FileInputStream(exportFile);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException();transfer(in,out);runOnUiThread(()->toast(s("saved")));}catch(Exception e){fail(e);}});});
    @Override public void onCreate(Bundle state){ThemeSkin.prepare(this);super.onCreate(state);skin=ThemeSkin.active;language=getIntent().getStringExtra("language");if(language==null)language="nl";Configuration cfg=new Configuration(getResources().getConfiguration());cfg.setLocale(Locale.forLanguageTag(language));words=createConfigurationContext(cfg);setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);ThemeSkin.window(this);if(state!=null&&state.getString("exportFile")!=null){File saved=new File(state.getString("exportFile"));try{if(saved.isFile()&&new File(getCacheDir(),"exports").getCanonicalFile().equals(saved.getCanonicalFile().getParentFile()))exportFile=saved;}catch(IOException ignored){}}
        getOnBackPressedDispatcher().addCallback(this,new androidx.activity.OnBackPressedCallback(true){@Override public void handleOnBackPressed(){if(busy)return;if(screen.equals("review"))capturePage();else if(screen.equals("count"))reviewPage();else finish();}});
        try{String path=state==null?getIntent().getStringExtra("picklistJob"):state.getString("job");boolean fresh=state==null&&getIntent().getBooleanExtra("newControl",false);if(path==null&&!fresh)path=getPreferences(0).getString("lastJob",null);if(path!=null){job=PicklistJob.load(this,path);restoreDraft();}else{job=PicklistJob.create(this);job.controlMode="picking".equals(getIntent().getStringExtra("controlMode"))?"picking":"final";job.captureMode=job.isPicking()?"stack":"box";job.save();}getPreferences(0).edit().putString("lastJob",job.directory.getPath()).apply();
            if(job.confirmed)dashboard();else if(state!=null&&state.getString("screen","").equals("count"))countPage();else if(!data.rows.isEmpty())reviewPage();else capturePage();
        }catch(Exception e){try{job=PicklistJob.create(this);job.controlMode="picking".equals(getIntent().getStringExtra("controlMode"))?"picking":"final";job.captureMode=job.isPicking()?"stack":"box";job.save();capturePage();}catch(Exception ignored){finish();}}
    }
    String s(String key,Object...args){int id=getResources().getIdentifier("ui_"+key,"string",getPackageName());return id==0?key:args.length==0?words.getString(id):words.getString(id,args);}
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private GradientDrawable surface(){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{skin.top,skin.bottom});d.setCornerRadius(dp(22));d.setStroke(dp(1),skin.accent);return d;}
    private TextView text(String value,int sp,boolean bold){TextView v=new TextView(this);v.setText(value);v.setTextColor(skin.text);v.setTextSize(sp);v.setTypeface(ReferenceArt.face(this,false,bold?850:550));v.setIncludeFontPadding(false);v.setPadding(dp(4),dp(6),dp(4),dp(6));return v;}
    private void gap(LinearLayout c,int n){c.addView(new View(this),new LinearLayout.LayoutParams(1,dp(n)));}
    private TextView action(String value,Runnable run,boolean primary){TextView v=text(value,17,true);v.setGravity(Gravity.CENTER);v.setMinHeight(dp(50));v.setPadding(dp(10),dp(10),dp(10),dp(10));GradientDrawable bg=surface();if(primary)bg.setColor(skin.accent);v.setBackground(bg);v.setTextColor(primary?(skin==ThemeSkin.LIGHT?Color.WHITE:0xff001b29):skin.text);v.setClickable(true);v.setFocusable(true);v.setOnClickListener(w->{if(busy)return;if(android.animation.ValueAnimator.areAnimatorsEnabled()){v.setScaleX(.97f);v.setScaleY(.97f);v.animate().scaleX(1).scaleY(1).setDuration(180).start();}run.run();});return v;}
    private void base(String page,String heading,int step){screen=page;if(currentToast!=null)currentToast.cancel();stopCamera();root=column();root.setPadding(dp(10),dp(6),dp(10),dp(10));root.setBackground(new UiArt.Backdrop(this).getBackground());FrameLayout shell=new FrameLayout(this);shell.setBackgroundColor(skin.background);shell.addView(root,new FrameLayout.LayoutParams(-1,-1));ViewCompat.setOnApplyWindowInsetsListener(shell,(v,i)->{androidx.core.graphics.Insets in=i.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());v.setPadding(in.left,in.top,in.right,in.bottom);return WindowInsetsCompat.CONSUMED;});setContentView(shell);ViewCompat.requestApplyInsets(shell);
        MenuHeader header=new MenuHeader(this,step==2?"document":step==3?"box":"qr",heading,s("back"),()->{if(!busy)getOnBackPressedDispatcher().onBackPressed();});
        if(page.equals("capture"))header.compact();header.title.setTag("picklist-heading");root.addView(header,new LinearLayout.LayoutParams(-1,-2));

        TextView badge=text(s("pl_step",step,s(step==2?"pl_picklist":step==3?"wizard_count":"pl_products")),14,true);badge.setGravity(Gravity.CENTER);badge.setBackground(surface());root.addView(badge,new LinearLayout.LayoutParams(-1,dp(34)));gap(root,6);
        LinearLayout progress=new LinearLayout(this);progress.setGravity(Gravity.CENTER_VERTICAL);String[] keys={"wizard_type","pl_picklist_short","wizard_count","pl_products"};for(int n=0;n<4;n++){
            final int position=n+1;LinearLayout cell=column();cell.setGravity(Gravity.CENTER);View dot=new View(this){final Paint p=new Paint(3);@Override protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=dp(7);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1.5f));p.setColor(position<=step?skin.accent:skin.secondary);c.drawCircle(x,y,r,p);if(position<step){Path check=new Path();check.moveTo(x-r*.5f,y);check.lineTo(x-r*.05f,y+r*.35f);check.lineTo(x+r*.55f,y-r*.4f);c.drawPath(check,p);}else if(position==step){p.setStyle(Paint.Style.FILL);c.drawCircle(x,y,r*.45f,p);}}};cell.addView(dot,new LinearLayout.LayoutParams(dp(20),dp(20)));
            TextView label=text(s(keys[n]),11,n+1==step);label.setPadding(0,0,0,0);label.setTextColor(n+1<=step?skin.accent:skin.secondary);label.setGravity(Gravity.CENTER);label.setMaxLines(1);label.setAutoSizeTextTypeUniformWithConfiguration(8,11,1,android.util.TypedValue.COMPLEX_UNIT_SP);label.setTag("picklist-progress-"+n);cell.addView(label,new LinearLayout.LayoutParams(-1,dp(18)));progress.addView(cell,new LinearLayout.LayoutParams(0,dp(40),1));
        }root.addView(progress,new LinearLayout.LayoutParams(-1,dp(44)));
        message=text("",13,false);message.setTextColor(skin.secondary);message.setGravity(Gravity.CENTER);root.addView(message,new LinearLayout.LayoutParams(-1,-2));body=column();body.setTag("picklist-"+page);ScrollView scroll=new ScrollView(this);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
    }
    private void footer(String label,Runnable run){gap(root,8);TextView next=action(label,run,true);next.setTag("picklist-next");root.addView(next,new LinearLayout.LayoutParams(-1,-2));}
    private void info(String value){TextView t=text(value,14,false);t.setGravity(Gravity.CENTER);body.addView(t);}
    private void capturePage(){base("capture",s("pl_capture"),2);message.setText(s("pl_frame"));int index=root.getChildCount()-1;root.removeViewAt(index);FrameLayout cameraFrame=new FrameLayout(this);cameraFrame.setBackground(surface());preview=new PreviewView(this);preview.setImplementationMode(PreviewView.ImplementationMode.COMPATIBLE);cameraFrame.addView(preview,new FrameLayout.LayoutParams(-1,-1));root.addView(cameraFrame,new LinearLayout.LayoutParams(-1,0,1));
        TextView pages=text(s("pl_pages",data.pages.size()),13,false);pages.setGravity(Gravity.CENTER);root.addView(pages);LinearLayout controls=new LinearLayout(this);TextView photo=action("◉  "+s("pl_photo"),this::takePhoto,true);photo.setTag("picklist-photo");controls.addView(photo,new LinearLayout.LayoutParams(0,dp(54),1));TextView pdf=action(s("pl_pdf"),()->documents.launch(new String[]{"application/pdf","image/*"}),false);pdf.setTag("picklist-import");LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(0,dp(54),.7f);pp.leftMargin=dp(8);controls.addView(pdf,pp);root.addView(controls);if(!data.pages.isEmpty())footer(s("pl_review"),this::reviewPage);
        if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED){ListenableFuture<ProcessCameraProvider> f=ProcessCameraProvider.getInstance(this);f.addListener(()->{if(destroyed||!screen.equals("capture"))return;try{provider=f.get();stopCamera();Preview live=new Preview.Builder().build();previewUseCase=live;camera=new ImageCapture.Builder().setCaptureMode(ImageCapture.CAPTURE_MODE_MAXIMIZE_QUALITY).build();live.setSurfaceProvider(preview.getSurfaceProvider());provider.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,live,camera);}catch(Exception e){message.setText(s("pl_camera_denied"));}},ContextCompat.getMainExecutor(this));}else permission.launch(Manifest.permission.CAMERA);
    }
    private void takePhoto(){if(camera==null){toast(s("pl_camera_denied"));return;}busy=true;message.setText(s("pl_reading"));File file=new File(job.directory,"page-"+UUID.randomUUID()+".jpg");camera.takePicture(new ImageCapture.OutputFileOptions.Builder(file).build(),ContextCompat.getMainExecutor(this),new ImageCapture.OnImageSavedCallback(){public void onImageSaved(ImageCapture.OutputFileResults r){readFiles(Collections.singletonList(file),Collections.singletonList("image/jpeg"));}public void onError(ImageCaptureException e){busy=false;fail(e);}});}
    void importDocuments(List<Uri> uris){busy=true;message.setText(s("pl_reading"));worker.execute(()->{List<File> files=new ArrayList<>();List<String> types=new ArrayList<>();try{for(Uri uri:uris){String type=getContentResolver().getType(uri);if(type==null)throw new IOException("Mime");if(!type.equals("application/pdf")&&!type.startsWith("image/"))throw new IOException("Mime");File file=new File(job.directory,"source-"+UUID.randomUUID()+(type.equals("application/pdf")?".pdf":".jpg"));try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException();transferLimited(in,out);}files.add(file);types.add(type);}readOnWorker(files,types);}catch(Exception e){busy=false;fail(e);}});}
    private void readFiles(List<File> files,List<String> types){worker.execute(()->readOnWorker(files,types));}
    private void readOnWorker(List<File> files,List<String> types){try{List<PicklistData.Page> pages=new ArrayList<>(data.pages);for(int i=0;i<files.size();i++)pages.addAll(PicklistReader.read(this,files.get(i),types.get(i)));PicklistData next=PicklistData.parse(pages);runOnUiThread(()->{if(destroyed)return;busy=false;data=next;reviewAcknowledged=false;saveDraft();reviewPage();});}catch(Exception e){busy=false;fail(e);}}
    void reviewPage(){lotColours.colours.clear();base("review",s("pl_review"),2);message.setText(s("pl_rows_total",data.rows.size(),data.total()));if(!data.order.isEmpty())info(s("pl_order",data.order));info(s("pl_pending"));if(!data.kind.isEmpty())info(s("pl_source_warning"));if(data.unparsed>0||data.missingPages>0)info(s("pl_uncertain"));if(data.declared>=0)info(s("pl_source_total",data.declared));
        for(int n=0;n<data.rows.size();n++){final int index=n;PicklistData.Row row=data.rows.get(n);LinearLayout line=new LinearLayout(this);line.setPadding(dp(8),dp(6),dp(8),dp(6));line.setGravity(Gravity.CENTER_VERTICAL);line.setBackground(surface());TextView product=text(row.article,16,true);product.setMaxLines(2);line.addView(product,new LinearLayout.LayoutParams(0,-2,1));TextView lot=text(row.lot+"\n"+row.expiry,13,false);lot.setTag("picklist-lot-"+index);lot.setTextColor(skin==ThemeSkin.LIGHT?skin.text:lotColours.colour(row.lot));line.addView(lot,new LinearLayout.LayoutParams(0,-2,1));TextView count=text(Integer.toString(row.quantity),20,true);count.setGravity(Gravity.CENTER);line.addView(count,new LinearLayout.LayoutParams(dp(40),-2));TextView edit=text("✎",23,true);edit.setContentDescription(s("pl_edit"));edit.setOnClickListener(v->editRow(index));line.addView(edit,new LinearLayout.LayoutParams(dp(38),dp(44)));body.addView(line);gap(body,6);}
        body.addView(action("+  "+s("pl_add_row"),()->editRow(-1),false));gap(body,8);body.addView(action(s("pl_source"),this::viewSource,false));body.addView(action(s("pl_add_page"),this::capturePage,false));
        CheckBox ack=new CheckBox(this);ack.setTag("picklist-ack");ack.setText(s("pl_ack"));ack.setTextColor(skin.text);ack.setChecked(reviewAcknowledged);ack.setOnCheckedChangeListener((v,on)->reviewAcknowledged=on);body.addView(ack);footer(s("pl_confirm"),()->{if(!reviewAcknowledged||data.rows.isEmpty()||data.missingPages>0||data.total()<1||data.total()>10000||(data.declared>=0&&data.declared!=data.total())){toast(s("pl_check_rows"));return;}job.rows.clear();job.rows.addAll(data.rows);job.order=data.order;job.allocation=null;data.unparsed=0;saveDraft();if(job.isPicking())confirmControl("stack");else countPage();});
    }
    private void editRow(int index){PicklistData.Row old=index<0?null:data.rows.get(index);LinearLayout panel=column();String[] keys={"pl_article","pl_lot","pl_expiry","pl_quantity"};String[] values=old==null?new String[]{"","","",""}:new String[]{old.article,old.lot,old.expiry,Integer.toString(old.quantity)};EditText[] inputs=new EditText[4];for(int n=0;n<4;n++){panel.addView(text(s(keys[n]),14,true));EditText in=new EditText(this);in.setTextColor(skin.text);in.setText(values[n]);in.setSingleLine();if(n==3)in.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);inputs[n]=in;panel.addView(in);}panel.setPadding(dp(16),dp(8),dp(16),dp(8));panel.setBackgroundColor(skin.background);android.app.AlertDialog dlg=new android.app.AlertDialog.Builder(this).setTitle(s("pl_edit")).setView(panel).setPositiveButton(s("done"),null).setNegativeButton(s("back"),null).setNeutralButton(s("delete"),null).create();dlg.setOnShowListener(d->{dlg.getButton(-1).setOnClickListener(v->{try{PicklistData.Row row=new PicklistData.Row(inputs[0].getText().toString(),inputs[1].getText().toString(),inputs[2].getText().toString(),Integer.parseInt(inputs[3].getText().toString()),true);if(index<0)data.rows.add(row);else data.rows.set(index,row);reviewAcknowledged=false;saveDraft();dlg.dismiss();reviewPage();}catch(Exception e){toast(s("pl_check_rows"));}});dlg.getButton(-3).setOnClickListener(v->{if(index>=0)data.rows.remove(index);reviewAcknowledged=false;saveDraft();dlg.dismiss();reviewPage();});});dlg.show();}
    void countPage(){base("count",s("pl_count"),3);message.setText(s("pl_auto"));CartonPlan plan=new CartonPlan(data.total(),job.capacity);if(job.allocation==null||job.allocation.length!=plan.boxes)job.allocation=plan.quantities.clone();TextView total=text(Integer.toString(plan.total),plan.boxes>1?34:52,true);total.setGravity(Gravity.CENTER);total.setTag("picklist-total");body.addView(total);info(s("pl_products"));ImageView art=new ImageView(this);art.setImageResource(R.drawable.wizard_full_box);art.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(art,new LinearLayout.LayoutParams(-1,dp(plan.boxes>1?38:65)));
        LinearLayout stats=new LinearLayout(this);TextView boxes=text(plan.boxes==1?s("pl_box_one"):s("pl_boxes",plan.boxes),24,true);boxes.setTextColor(skin==ThemeSkin.LIGHT?0xff12772c:0xff50f346);boxes.setGravity(Gravity.CENTER);boxes.setTag("picklist-boxes");stats.addView(boxes,new LinearLayout.LayoutParams(0,dp(46),1));TextView average=text(s("pl_average",String.format(Locale.forLanguageTag(language),"%.1f",plan.average())),17,true);average.setGravity(Gravity.CENTER);stats.addView(average,new LinearLayout.LayoutParams(0,dp(58),1));body.addView(stats);
        TextView capacityChoice=action(s(job.capacity==113?"pl_standard":"pl_large")+" · "+plan.dimensions()+" · "+s("pl_max",job.capacity)+"  ▾",()->{new android.app.AlertDialog.Builder(this).setTitle(s("pl_proposal")).setSingleChoiceItems(new String[]{s("pl_standard")+" · 70 × 50 × 30 cm · 113",s("pl_large")+" · 80 × 50 × 30 cm · 125"},job.capacity==113?0:1,(dialog,which)->{job.capacity=which==0?113:125;job.allocation=null;saveDraft();dialog.dismiss();countPage();}).show();},false);capacityChoice.setTextSize(13);capacityChoice.setMinHeight(dp(40));body.addView(capacityChoice);info(s("pl_proposal"));for(int n=0;n<plan.boxes;n++){LinearLayout line=column();line.setBackground(surface());TextView label=text(s("pl_carton",n+1,plan.boxes)+" · "+job.allocation[n]+" / "+plan.capacity+" · "+(plan.capacity-job.allocation[n]==1?s("pl_free_one"):s("pl_free",plan.capacity-job.allocation[n])),12,true);line.addView(label);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(plan.capacity);bar.setProgress(job.allocation[n]);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(skin.accent));line.addView(bar,new LinearLayout.LayoutParams(-1,dp(5)));final int index=n;line.setTag("picklist-allocation-"+n);line.setClickable(true);line.setFocusable(true);line.setOnClickListener(v->editAllocation(index,plan));body.addView(line);gap(body,6);}int allocated=0;for(int amount:job.allocation)allocated+=amount;TextView sum=text(s("pl_plan_total",allocated,plan.total),13,false);sum.setTextColor(allocated==plan.total?skin.secondary:skin==ThemeSkin.LIGHT?0xffac1530:0xffff879a);body.addView(sum);info(s("pl_not_scanned"));body.addView(action(s("pl_adjust"),this::reviewPage,false));footer(s("pl_continue"),()->{try{new CartonPlan(data.total(),job.capacity,job.allocation);choosePackingStage();}catch(Exception e){fail(e);}});
    }
    private void choosePackingStage(){new ControlStagePopup(this,this::s,mode->confirmControl(mode)).show();}
    private void confirmControl(String mode){try{job.captureMode=mode;job.confirmed=true;job.save();dashboard();openCarton(0);}catch(Exception error){fail(error);}}
    private void editAllocation(int index,CartonPlan plan){EditText value=new EditText(this);value.setText(Integer.toString(job.allocation[index]));value.setTextColor(skin.text);value.setBackgroundColor(skin.background);value.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);value.setSelectAllOnFocus(true);android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(this).setTitle(s("pl_carton",index+1,plan.boxes)+" · "+s("pl_max",plan.capacity)).setView(value).setPositiveButton(s("done"),null).setNegativeButton(s("back"),null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{int n=Integer.parseInt(value.getText().toString());if(n<1||n>plan.capacity)throw new IllegalArgumentException();job.allocation[index]=n;saveDraft();dialog.dismiss();countPage();}catch(Exception e){value.setError(s("pl_max",plan.capacity));}}));dialog.show();}
    private void openCarton(int index){try{CartonPlan plan=job.plan();String folder=job.cartons.get(index);Intent intent=new Intent(this,BoxScanActivity.class).putExtra("language",language).putExtra("flowMode",job.captureMode).putExtra("expected",plan.quantities[index]).putExtra("picklistJob",job.directory.getPath()).putExtra("cartonIndex",index);if(folder!=null)intent.putExtra("cartonFolder",folder);scan.launch(intent);}catch(Exception e){fail(e);}}
    void dashboard(){base("job",s(job.isPicking()?"picking_control":"pl_control"),4);try{job=PicklistJob.load(this,job.directory.getPath());CartonPlan plan=job.plan();Map<String,Integer> total=job.totals();boolean complete=job.complete();message.setText(s(complete?"pl_matched":"pl_not_complete"));for(int n=0;n<plan.boxes;n++){final int index=n;boolean checked=job.observed(n)!=null;body.addView(action((job.isPicking()?s("picking_control"):s("pl_carton",n+1,plan.boxes))+" · "+plan.quantities[n]+" · "+s(checked?"pl_reviewed":"pl_not_scanned"),()->openCarton(index),false));gap(body,8);}for(PicklistData.Row row:job.rows)info(row.article+" · "+row.lot+" · "+row.expiry+" · "+total.getOrDefault(row.key(),0)+" / "+PicklistData.expected(job.rows).get(row.key()));info(s("pl_no_auto"));if(complete){body.addView(action(s("local_save"),()->buildExport(true),true));gap(body,8);body.addView(action(s("share"),()->buildExport(false),false));}body.addView(action(s("pl_new"),()->{try{job=PicklistJob.create(this);job.controlMode="picking".equals(getIntent().getStringExtra("controlMode"))?"picking":"final";job.captureMode=job.isPicking()?"stack":"box";job.save();data=new PicklistData();getPreferences(0).edit().putString("lastJob",job.directory.getPath()).apply();capturePage();}catch(Exception e){fail(e);}},false));}catch(Exception e){fail(e);}}
    private void buildExport(boolean local){busy=true;worker.execute(()->{try{if(!job.complete())throw new IOException(s("pl_not_complete"));File exports=new File(getCacheDir(),"exports");exports.mkdirs();File out=new File(exports,(job.isPicking()?"BMD-picking-controle-":"BMD-eindcontrole-")+System.currentTimeMillis()+".zip");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(out))){put(zip,"picklist.json",job.json().toString(2).getBytes(StandardCharsets.UTF_8));StringBuilder csv=new StringBuilder("Product,Lot,Expiry,Expected,Observed\n");Map<String,Integer> counts=job.totals();for(java.util.Map.Entry<String,Integer> entry:PicklistData.expected(job.rows).entrySet()){String key=entry.getKey();String[] parts={key.substring(0,key.indexOf('|')),key.substring(key.indexOf('|')+1,key.lastIndexOf('|')),key.substring(key.lastIndexOf('|')+1)};csv.append(csv(parts[0])).append(',').append(csv(parts[1])).append(',').append(parts[2]).append(',').append(entry.getValue()).append(',').append(counts.getOrDefault(entry.getKey(),0)).append('\n');}put(zip,"control.csv",csv.toString().getBytes(StandardCharsets.UTF_8));for(File file:Objects.requireNonNull(job.directory.listFiles()))if(!file.getName().equals("picklist.json"))zipFile(zip,file,"source/"+file.getName());for(Map.Entry<Integer,String> box:job.cartons.entrySet())for(File file:Objects.requireNonNull(new File(box.getValue()).listFiles()))if(file.isFile())zipFile(zip,file,"carton-"+(box.getKey()+1)+"/"+file.getName());}exportFile=out;runOnUiThread(()->{busy=false;if(local)save.launch(out.getName());else{Uri uri=FileProvider.getUriForFile(this,getPackageName()+".provider",out);startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("application/zip").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),s("share")));}});}catch(Exception e){busy=false;fail(e);}});}
    private static String csv(String s){if(s.matches("^[=+@-].*"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
    private static void put(ZipOutputStream z,String name,byte[] bytes)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(bytes);z.closeEntry();}
    private static void zipFile(ZipOutputStream z,File file,String name)throws IOException{z.putNextEntry(new ZipEntry(name));try(InputStream in=new FileInputStream(file)){transfer(in,z);}z.closeEntry();}
    private void viewSource(){File[] files=job.directory.listFiles(f->f.getName().startsWith("source-")||f.getName().startsWith("page-"));if(files==null||files.length==0)return;String[] names=new String[files.length];for(int i=0;i<files.length;i++)names[i]=s("pl_picklist")+" "+(i+1)+(files[i].getName().endsWith("pdf")?" · PDF":" · "+s("pl_photo"));new android.app.AlertDialog.Builder(this).setTitle(s("pl_source")).setItems(names,(d,n)->{try{Uri uri=FileProvider.getUriForFile(this,getPackageName()+".provider",files[n]);startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,files[n].getName().endsWith("pdf")?"application/pdf":"image/jpeg").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){fail(e);}}).show();}
    private static void transfer(InputStream in,OutputStream out)throws IOException{byte[] buffer=new byte[16384];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}
    private static void transferLimited(InputStream in,OutputStream out)throws IOException{byte[] buffer=new byte[16384];int n;long bytes=0;while((n=in.read(buffer))!=-1){bytes+=n;if(bytes>100_000_000)throw new IOException("100 MB");out.write(buffer,0,n);}}
    private void saveDraft(){if(job==null||job.confirmed)return;try{job.rows.clear();job.rows.addAll(data.rows);job.save();JSONObject o=new JSONObject().put("order",data.order).put("declared",data.declared).put("unparsed",data.unparsed).put("missing",data.missingPages).put("kind",data.kind);JSONArray pages=new JSONArray();for(PicklistData.Page page:data.pages)pages.put(new JSONObject().put("digest",page.digest).put("lines",new JSONArray(page.lines)));o.put("pages",pages);android.util.AtomicFile target=new android.util.AtomicFile(new File(job.directory,"draft.json"));FileOutputStream stream=target.startWrite();try{stream.write(o.toString().getBytes(StandardCharsets.UTF_8));target.finishWrite(stream);}catch(Exception error){target.failWrite(stream);throw error;}}catch(Exception e){fail(e);}}
    private void restoreDraft()throws Exception{File file=new File(job.directory,"draft.json");if(file.exists()){JSONObject o=new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));data.order=o.optString("order");data.declared=o.optInt("declared",-1);data.unparsed=o.optInt("unparsed");data.missingPages=o.optInt("missing");data.kind=o.optString("kind");JSONArray pages=o.getJSONArray("pages");for(int n=0;n<pages.length();n++){JSONObject p=pages.getJSONObject(n);List<String> lines=new ArrayList<>();JSONArray ls=p.getJSONArray("lines");for(int i=0;i<ls.length();i++)lines.add(ls.getString(i));data.pages.add(new PicklistData.Page(lines,p.getString("digest")));}}data.rows.addAll(job.rows);}
    private void stopCamera(){if(provider!=null){if(camera!=null)provider.unbind(camera);if(previewUseCase!=null)provider.unbind(previewUseCase);}camera=null;previewUseCase=null;}
    private void toast(String s){if(currentToast!=null)currentToast.cancel();currentToast=Toast.makeText(this,s,Toast.LENGTH_LONG);currentToast.show();}
    private void fail(Exception e){runOnUiThread(()->{if(!destroyed){busy=false;toast(s("pl_error"));if(message!=null)message.setText(s("pl_error"));android.util.Log.e("BMD-picklist","Read/control failed",e);}});}
    @Override protected void onSaveInstanceState(Bundle out){if(job!=null)out.putString("job",job.directory.getPath());out.putString("screen",screen);if(exportFile!=null)out.putString("exportFile",exportFile.getPath());saveDraft();super.onSaveInstanceState(out);}
    @Override protected void onDestroy(){destroyed=true;stopCamera();worker.shutdown();super.onDestroy();}
}
